/njs_int_t
njs_string_set(njs_vm_t *vm, njs_value_t *value, const u_char *start,
    uint32_t size)
{
    u_char        *dst;
    const u_char  *src;

    /*
     * njs_string_set() is used for creating strings that may outlive the
     * original buffer (e.g. script source).  Do not keep external pointers
     * to caller-owned memory for long strings, always copy into VM pool.
     */

    if (size > NJS_STRING_SHORT) {
        /* length=0: treated as byte string until validated when needed. */
        return njs_string_new(vm, value, start, size, 0);
    }

    value->type = NJS_STRING;
    njs_string_truth(value, size);

    value->short_string.size = size;
    value->short_string.length = 0;

    dst = value->short_string.start;
    src = start;

    while (size != 0) {
        /* The maximum size is just 14 bytes. */
        njs_pragma_loop_disable_vectorization;

        *dst++ = *src++;
        size--;
    }

    return NJS_OK;
}
